import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';
import * as primitives from '@/primitives';
import * as text from '@/text';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry } = ctx.THREE;

  // Root container – the adapter will apply position/rotation/scale.
  const root = new Group();

  // ------- Plane (textured backdrop) -------
  // Use the image aspect ratio (512:320 ≈ 1.6) for a natural size.
  const planeWidth = 1.6;
  const planeHeight = 1.0;
  const geometry = new PlaneGeometry(planeWidth, planeHeight);
  const material = new MeshBasicNodeMaterial();
  const plane = new Mesh(geometry, material);
  root.add(plane);

  // Load texture asynchronously; assign when ready.
  const texturePromise = ctx.textureLoader.loadTexture(config.imageUrl);
  texturePromise.then((tex) => {
    material.map = tex;
    material.needsUpdate = true;
  });

  // ------- Text content -------
  const items =
    config.textContent ??
    config.intent?.visualSpec?.textContent ??
    [];

  const textObjects = [];
  for (const item of items) {
    const opts = {
      fontSize: item.typography?.fontSize ?? 39,
      color: (config.intent?.visualSpec?.colors?.ink ?? '#16161d'),
      align: 'left',
    };
    const txt = ctx.fontAtlas.createText(item.text, opts);
    // Position the text slightly above the plane (z = 0.01) to avoid z‑fighting.
    txt.position.set(0, 0, 0.01);
    root.add(txt);
    textObjects.push(txt);
  }

  // ------- Event handlers (none for this node) -------
  root.userData.handlers = {};

  // ------- Cleanup ----------
  const timelines = [];

  root.userData.cleanup = () => {
    // Dispose geometry and material.
    geometry.dispose();
    material.dispose();

    // Dispose texture if it has loaded.
    texturePromise.then((tex) => {
      if (tex?.dispose) tex.dispose();
    });

    // Dispose any text objects that expose a dispose method.
    for (const txt of textObjects) {
      if (typeof txt.dispose === 'function') txt.dispose();
    }

    // Kill any GSAP timelines we may have created.
    for (const tl of timelines) tl.kill();
  };

  return root;
}
